program.source:
Function total <- SumUpTo(n As Integer)
  Define total As Integer;
  total <- n + SumUpTo(n - 1);
EndFunction

Algorithm Main
  Define n As Integer;
  Read n;
  Write SumUpTo(n);
EndAlgorithm

